:root { --bg: #f6f7fb; --panel: #ffffff; --text: #1c1f2b; --muted: #6b7185; --border: #e4e6ef; --accent: #4f46e5; --accent-soft: #eef0ff; --ok: #0f9d58; --warn: #d97706; --info: #2563eb; font-family: Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; color: var(--text); background: var(--bg); }* { box-sizing: border-box; }body { margin: 0px; }h1 { font-size: 22px; margin: 0px 0px 4px; }h2 { font-size: 15px; margin: 0px 0px 14px; }p { margin: 0px; }a { color: var(--accent); }.muted { color: var(--muted); }.small { font-size: 12px; }.boot { display: grid; place-items: center; height: 100vh; }.spinner { width: 28px; height: 28px; border-radius: 50%; border-top-style: ; border-top-width: ; border-right-color: ; border-right-style: ; border-right-width: ; border-bottom-color: ; border-bottom-style: ; border-bottom-width: ; border-left-color: ; border-left-style: ; border-left-width: ; border-image-source: ; border-image-slice: ; border-image-width: ; border-image-outset: ; border-image-repeat: ; border-top-color: var(--accent); animation: 0.8s linear 0s infinite normal none running spin; }@keyframes spin { 
  100% { transform: rotate(360deg); }
}.shell { min-height: 100vh; display: flex; flex-direction: column; }.topbar { height: 56px; display: flex; align-items: center; gap: 20px; padding: 0px 20px; background: var(--panel); border-bottom: 1px solid var(--border); position: sticky; top: 0px; z-index: 5; }.brand { display: flex; align-items: center; gap: 8px; font-weight: 700; }.brand-mark { width: 28px; height: 28px; border-radius: 8px; background: var(--accent); color: rgb(255, 255, 255); display: grid; place-items: center; font-size: 14px; }.switcher { position: relative; }.switcher-button { display: flex; align-items: center; gap: 8px; padding: 6px 12px; border-radius: 8px; border: 1px solid var(--border); background: rgb(255, 255, 255); cursor: pointer; font: inherit; }.switcher-button:hover { background: rgb(250, 251, 255); }.switcher-name { font-weight: 600; }.caret { color: var(--muted); font-size: 11px; }.ws-dot { width: 10px; height: 10px; border-radius: 3px; display: inline-block; flex: 0 0 auto; }.switcher-menu { position: absolute; top: 42px; left: 0px; min-width: 260px; list-style: none; margin: 0px; padding: 6px; background: rgb(255, 255, 255); border: 1px solid var(--border); border-radius: 10px; box-shadow: rgba(20, 24, 50, 0.12) 0px 12px 30px; }.switcher-label { padding: 6px 10px; font-size: 11px; text-transform: uppercase; letter-spacing: 0.04em; color: var(--muted); }.switcher-menu button { width: 100%; display: flex; align-items: center; gap: 10px; padding: 8px 10px; border: 0px; background: none; border-radius: 6px; cursor: pointer; font: inherit; text-align: left; }.switcher-menu button span:nth-child(2) { flex: 1 1 0%; }.switcher-menu button:hover, .switcher-menu button.active { background: var(--accent-soft); }.topbar-right { margin-left: auto; display: flex; align-items: center; gap: 10px; }.plan-badge { font-size: 12px; font-weight: 600; padding: 3px 10px; border-radius: 999px; }.plan-business { background: rgb(254, 243, 199); color: rgb(146, 64, 14); }.plan-free { background: rgb(229, 231, 235); color: rgb(55, 65, 81); }.avatar { width: 32px; height: 32px; border-radius: 50%; background: rgb(199, 210, 254); color: rgb(55, 48, 163); display: grid; place-items: center; font-size: 12px; font-weight: 700; }.user-name { font-size: 14px; }.body { flex: 1 1 0%; display: flex; }.sidebar { width: 220px; padding: 16px 10px; border-right: 1px solid var(--border); background: var(--panel); display: flex; flex-direction: column; gap: 2px; }.nav-link { display: flex; align-items: center; gap: 10px; padding: 9px 12px; border-radius: 8px; color: var(--text); text-decoration: none; font-size: 14px; }.nav-link:hover { background: rgb(243, 244, 250); }.nav-link.active { background: var(--accent-soft); color: var(--accent); font-weight: 600; }.nav-icon { width: 18px; text-align: center; color: var(--muted); }.nav-link.active .nav-icon { color: var(--accent); }.lock { margin-left: auto; font-size: 12px; }.content { flex: 1 1 0%; padding: 28px 32px; overflow: auto; }.page { max-width: 1100px; display: flex; flex-direction: column; gap: 20px; }.page-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; }.sync { padding-top: 6px; }.card { background: var(--panel); border: 1px solid var(--border); border-radius: 12px; padding: 20px; }.grid-2 { display: grid; grid-template-columns: 1.4fr 1fr; gap: 20px; }@media (max-width: 900px) {
  .grid-2 { grid-template-columns: 1fr; }
  .sidebar { width: 64px; }
  .nav-link span:nth-child(2) { display: none; }
}.stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; }.stat { background: var(--panel); border: 1px solid var(--border); border-radius: 12px; padding: 16px 18px; display: flex; flex-direction: column; gap: 4px; }.stat-value { font-size: 26px; font-weight: 700; }.stat-label { color: var(--muted); font-size: 13px; }.project-list, .activity, .features, .meetings { list-style: none; margin: 0px; padding: 0px; }.project { display: grid; grid-template-columns: 1fr auto; gap: 6px 12px; padding: 12px 0px; border-bottom: 1px solid var(--border); }.project:last-child { border-bottom: 0px; }.project-main { display: flex; flex-direction: column; gap: 2px; }.project-name { font-weight: 600; }.project .progress { grid-column: 1 / -1; }.progress { height: 6px; background: rgb(238, 240, 246); border-radius: 99px; overflow: hidden; }.progress-bar { height: 100%; background: var(--accent); border-radius: 99px; }.activity li { display: flex; flex-direction: column; gap: 2px; padding: 10px 0px; border-bottom: 1px solid var(--border); font-size: 14px; }.activity li:last-child { border-bottom: 0px; }.pill { font-size: 12px; padding: 2px 10px; border-radius: 999px; background: rgb(238, 240, 246); white-space: nowrap; align-self: start; }.pill.ok { background: rgb(230, 246, 238); color: var(--ok); }.pill.warn { background: rgb(253, 242, 227); color: var(--warn); }.pill.info { background: rgb(232, 239, 255); color: var(--info); }.pill.locked { background: rgb(243, 244, 246); color: rgb(75, 85, 99); }.upgrade-banner { display: flex; align-items: center; justify-content: space-between; gap: 16px; background: linear-gradient(90deg, rgb(79, 70, 229), rgb(124, 58, 237)); color: rgb(255, 255, 255); border-radius: 12px; padding: 14px 18px; }.upgrade-banner div { display: flex; gap: 8px; flex-wrap: wrap; }.btn { display: inline-flex; align-items: center; justify-content: center; gap: 6px; padding: 8px 14px; border-radius: 8px; border: 1px solid var(--accent); background: var(--accent); color: rgb(255, 255, 255); font-style: inherit; font-variant: inherit; font-stretch: inherit; line-height: inherit; font-family: inherit; font-size: 14px; font-weight: 600; cursor: pointer; text-decoration: none; }.btn:disabled { opacity: 0.55; cursor: not-allowed; }.btn-light { background: rgb(255, 255, 255); color: var(--accent); border-color: rgb(255, 255, 255); }.btn-ghost { background: rgb(255, 255, 255); color: var(--text); border-color: var(--border); }.btn.small { padding: 4px 10px; font-size: 12px; }.input { width: 100%; padding: 8px 10px; border: 1px solid var(--border); border-radius: 8px; font-style: inherit; font-variant: inherit; font-weight: inherit; font-stretch: inherit; line-height: inherit; font-family: inherit; font-size: 14px; background: rgb(255, 255, 255); }.input:focus { outline: 2px solid var(--accent-soft); border-color: var(--accent); }.search { margin-bottom: 12px; max-width: 320px; }.table { width: 100%; border-collapse: collapse; font-size: 14px; }.table th { text-align: left; font-size: 12px; color: var(--muted); font-weight: 600; padding: 8px 10px; border-bottom: 1px solid var(--border); }.table td { padding: 10px; border-bottom: 1px solid var(--border); }.table tr:last-child td { border-bottom: 0px; }.clickable { cursor: pointer; }.clickable:hover { background: rgb(250, 251, 255); }.member-name { font-weight: 600; }.drawer-backdrop { position: fixed; inset: 0px; background: rgba(15, 18, 35, 0.3); display: flex; justify-content: flex-end; z-index: 10; }.drawer { width: 380px; background: rgb(255, 255, 255); height: 100%; padding: 28px 24px; position: relative; box-shadow: rgba(0, 0, 0, 0.08) -8px 0px 30px; }.drawer-close { position: absolute; top: 12px; right: 14px; border: 0px; background: none; font-size: 22px; cursor: pointer; color: var(--muted); }.profile { display: flex; flex-direction: column; gap: 4px; }.profile-avatar { width: 56px; height: 56px; border-radius: 50%; background: rgb(199, 210, 254); color: rgb(55, 48, 163); display: grid; place-items: center; font-size: 22px; font-weight: 700; margin-bottom: 8px; }.profile-name { margin: 0px; font-size: 18px; }.profile-fields { display: grid; grid-template-columns: 110px 1fr; gap: 10px; margin-top: 18px; font-size: 14px; }.profile-fields dt { color: var(--muted); }.profile-fields dd { margin: 0px; }.loading { color: var(--muted); padding: 12px 0px; font-size: 14px; }.alert { background: rgb(253, 236, 236); color: rgb(180, 35, 24); padding: 10px 12px; border-radius: 8px; font-size: 14px; }.plan-card { display: flex; flex-direction: column; gap: 8px; }.plan-name { font-size: 26px; margin: 0px; }.plan-price { font-size: 20px; font-weight: 600; }.seats { display: flex; flex-direction: column; gap: 6px; margin: 6px 0px; }.feature { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 10px 0px; border-bottom: 1px solid var(--border); }.feature:last-child { border-bottom: 0px; }.feature.off strong { color: var(--muted); }.locked-panel { background: rgb(255, 255, 255); border: 1px dashed var(--border); border-radius: 12px; padding: 48px; text-align: center; display: flex; flex-direction: column; gap: 10px; align-items: center; }.lock-big { font-size: 34px; }.bars { display: flex; align-items: flex-end; gap: 18px; height: 190px; padding-top: 10px; }.bar-col { display: flex; flex-direction: column; align-items: center; gap: 6px; flex: 1 1 0%; }.bar { width: 100%; max-width: 48px; background: linear-gradient(rgb(129, 140, 248), rgb(79, 70, 229)); border-radius: 6px 6px 0px 0px; }.field { display: flex; flex-direction: column; gap: 6px; font-size: 13px; font-weight: 500; }.form-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 14px; margin-bottom: 14px; }.toggles { border: 1px solid var(--border); border-radius: 10px; padding: 12px 16px; display: flex; flex-direction: column; gap: 8px; margin: 0px 0px 16px; }.toggles legend { font-size: 13px; font-weight: 600; padding: 0px 6px; }.toggle { display: flex; align-items: center; gap: 8px; font-size: 14px; }.form-actions { display: flex; align-items: center; gap: 10px; }.saved { color: var(--ok); font-size: 14px; font-weight: 600; }.schedule-form { display: flex; flex-direction: column; gap: 14px; }.schedule-form .form-grid { margin: 0px; }.preview { background: var(--accent-soft); color: rgb(49, 46, 129); padding: 10px 12px; border-radius: 8px; font-size: 14px; }.confirm { background: rgb(230, 246, 238); color: rgb(6, 95, 70); padding: 10px 12px; border-radius: 8px; font-size: 14px; }.tz-chip { font-size: 12px; background: rgb(255, 255, 255); border: 1px solid var(--border); padding: 4px 10px; border-radius: 999px; }.meeting { display: flex; align-items: center; gap: 12px; padding: 10px 0px; border-bottom: 1px solid var(--border); }.meeting:last-child { border-bottom: 0px; }.date-badge { width: 56px; text-align: center; font-size: 12px; font-weight: 700; background: var(--accent-soft); color: var(--accent); padding: 8px 4px; border-radius: 8px; text-transform: uppercase; }.meeting-main { flex: 1 1 0%; display: flex; flex-direction: column; gap: 2px; }

